//! The code generated by `#[derive(Keyed)]`

use std::collections::HashSet;

use proc_macro2::TokenStream as TokenStream2;
use quote::{quote, quote_spanned};
use syn::{
    Data, DeriveInput, Error, Fields, GenericArgument, Ident, PathArguments, Token, Type,
    punctuated::Punctuated, spanned::Spanned,
};

/// Expands `#[derive(Keyed)]`: the key type and the `key` method, from the fields named by `#[key(...)]`.
pub(crate) fn expand(input: &DeriveInput) -> syn::Result<TokenStream2> {
    let name = &input.ident;
    if !input.generics.params.is_empty() {
        return Err(Error::new(
            input.generics.span(),
            "`Keyed` cannot be derived for a generic type",
        ));
    }
    let Data::Struct(data) = &input.data else {
        return Err(Error::new(
            name.span(),
            "`Keyed` can only be derived for a struct",
        ));
    };
    let Fields::Named(fields) = &data.fields else {
        return Err(Error::new(
            name.span(),
            "`Keyed` can only be derived for a struct with named fields",
        ));
    };

    let key_fields = key_fields(input)?;
    let mut types = Vec::new();
    let mut values = Vec::new();
    for key in &key_fields {
        let Some(field) = fields
            .named
            .iter()
            .find(|field| field.ident.as_ref() == Some(key))
        else {
            return Err(Error::new(
                key.span(),
                format!("`{name}` has no field `{key}`"),
            ));
        };
        let (ty, value) = borrowed(key, &field.ty);
        types.push(ty);
        values.push(value);
    }

    let (key_type, key_value) = if let ([ty], [value]) = (types.as_slice(), values.as_slice()) {
        (ty.clone(), value.clone())
    } else {
        (quote!((#(#types),*)), quote!((#(#values),*)))
    };

    Ok(quote! {
        impl ::cta_model::Keyed for #name {
            type Key<'a> = #key_type;

            fn key(&self) -> Self::Key<'_> {
                #key_value
            }
        }
    })
}

/// The fields of `#[key(field, ...)]`, which must be given once, with distinct fields
fn key_fields(input: &DeriveInput) -> syn::Result<Vec<Ident>> {
    let mut attrs = input
        .attrs
        .iter()
        .filter(|attr| attr.path().is_ident("key"));
    let Some(attr) = attrs.next() else {
        return Err(Error::new(
            input.ident.span(),
            "missing the fields of the key, e.g. `#[key(name)]`",
        ));
    };
    if let Some(extra) = attrs.next() {
        return Err(Error::new(extra.span(), "`#[key]` given twice"));
    }
    let fields: Vec<Ident> = attr
        .parse_args_with(Punctuated::<Ident, Token![,]>::parse_terminated)?
        .into_iter()
        .collect();
    if fields.is_empty() {
        return Err(Error::new(
            attr.span(),
            "the key needs at least one field, e.g. `#[key(name)]`",
        ));
    }
    let mut seen = HashSet::new();
    for field in &fields {
        if !seen.insert(field.to_string()) {
            return Err(Error::new(
                field.span(),
                format!("`{field}` is given twice"),
            ));
        }
    }
    Ok(fields)
}

/// The type and the value of a field in the key: `String` as `&str`, `Option<String>` as `Option<&str>`, other types
/// copied.
fn borrowed(field: &Ident, ty: &Type) -> (TokenStream2, TokenStream2) {
    if is_string(ty) {
        (
            quote!(&'a ::core::primitive::str),
            quote_spanned!(field.span()=> self.#field.as_str()),
        )
    } else if option_inner(ty).is_some_and(is_string) {
        (
            quote!(::core::option::Option<&'a ::core::primitive::str>),
            quote_spanned!(field.span()=> self.#field.as_deref()),
        )
    } else {
        (quote!(#ty), quote_spanned!(field.span()=> self.#field))
    }
}

fn is_string(ty: &Type) -> bool {
    matches!(ty, Type::Path(path) if path.qself.is_none() && path.path.is_ident("String"))
}

/// `T` of `Option<T>`
fn option_inner(ty: &Type) -> Option<&Type> {
    let Type::Path(path) = ty else { return None };
    let segment = path.path.segments.last()?;
    let PathArguments::AngleBracketed(args) = &segment.arguments else {
        return None;
    };
    match args.args.first() {
        Some(GenericArgument::Type(inner)) if segment.ident == "Option" && args.args.len() == 1 => {
            Some(inner)
        }
        _ => None,
    }
}
